        "asset_type": "CRYPTOCURRENCY",
        "quantity": 0.1,
        "current_price": 50000,
        "market_value": 5000.0
      }
    ],
    "cash_balance": 5000,
    "total_value": 100000
  },
  "investment_policy": {
    "target_allocations": {},
    "restrictions": [
      {
        "restriction_type": "CLASS_RANGE",
        "parameters_json": {
          "asset_class": "STOCK",
          "min_pct": 0.2,
          "max_pct": 0.4
        }
      },
      {
        "restriction_type": "CLASS_RANGE",
        "parameters_json": {
          "asset_class": "BOND",
          "min_pct": 0.45,
          "max_pct": 0.65
        }
      },
      {
        "restriction_type": "CLASS_RANGE",
        "parameters_json": {
          "asset_class": "CASH",
          "min_pct": 0.05,
          "max_pct": 0.25
        }
      },
